<script lang="ts">import {noticeTypes,activeNotices} from '$lib/data/notices';import NoticeCard from '$lib/components/NoticeCard.svelte';let type=$state('All updates');let query=$state('');let filtered=$derived(activeNotices().filter(n=>(type==='All updates'||n.type===type)&&(n.title+' '+n.excerpt).toLowerCase().includes(query.toLowerCase())));</script>
<svelte:head><title>Noticeboard — beVisioneers Harare Hub</title><meta name="description" content="Events, stories, opportunities, products, services and promotions from the beVisioneers Harare community."/></svelte:head>
<section class="page-hero yellow"><p class="eyebrow">NEWS, IDEAS & POSSIBILITIES</p><h1>The hub<br/>noticeboard.<span class="heading-star" aria-hidden="true">✳</span></h1><p>A place for what’s happening, what’s growing,<br class="desktop-break"/> and what our fellows have to offer.</p></section>
<section class="section"><div class="board-tools"><div class="category-tabs" aria-label="Notice categories">{#each noticeTypes as t}<button class:active={type===t} aria-pressed={type===t} onclick={()=>type=t}>{t}</button>{/each}</div><label class="board-search">Search updates<input type="search" bind:value={query} placeholder="Find an update…"/></label></div><div class="results-bar"><p aria-live="polite">{filtered.length} published {filtered.length===1?'update':'updates'}{type==='All updates'?'':' · '+type}</p></div>{#if filtered.length}<div class="notice-grid">{#each filtered as notice}<NoticeCard {notice}/>{/each}</div>{:else}<div class="empty-state notice-empty"><span aria-hidden="true">↗</span><p class="eyebrow">WATCH THIS SPACE</p><h2>{query?'No matching updates.':type==='All updates'?'The next good thing starts here.':'No '+type.toLowerCase()+' published yet.'}</h2><p>{query?'Try a different search or category.':'Our leadership team will share chapter events, articles, opportunities, and fellow offers here. Come back to see what’s new.'}</p>{#if query||type!=='All updates'}<button class="button outline" onclick={()=>{type='All updates';query='';}}>View all updates <span>↗</span></button>{:else}<a class="button dark" href="/fellows">Meet our fellows <span>↗</span></a>{/if}</div>{/if}<div class="board-info"><div><h3>Connect with the community.</h3><p>Discover events and ideas, find opportunities to collaborate, and explore products, services, and promotions as fellows make them available.</p></div><div><h3>Have something to share?</h3><p>Fellows can share their news and offers with the Harare Hub leadership for publication on the noticeboard.</p></div></div></section>
